function c(e){if(!e&&e!==0)return"-";const r=Math.floor(Math.abs(e)/60),n=Math.abs(e)%60;return`${e<0?"-":""}${r}h ${String(n).padStart(2,"0")}m`}function m(e,r="pl"){const n=["Styczeń","Luty","Marzec","Kwiecień","Maj","Czerwiec","Lipiec","Sierpień","Wrzesień","Październik","Listopad","Grudzień"],i=["Januar","Februar","März","April","Mai","Juni","Juli","August","September","Oktober","November","Dezember"],[a,t]=e.split("-"),s=r==="de"?i:n,o=parseInt(t,10)-1;return`${s[o]||t} ${a}`}export{c as a,m};
